
local um=[==[]==]
local hqgi=
(function(...)
local yezis={159,9,72,4,56,10,11,129,32,90,63,92,81,69,3,103,224,35,51,84,251,132,128,240,124,213,55}
local jdnq=bit32 or bit
local jvel=jdnq.bxor
for qjp=1,#yezis do yezis[qjp]=jvel(yezis[qjp],(9*qjp+71)%256) end
local qx="ABCDEFGHIJKLMNOPQRSTUVWXYZabcdefghijklmnopqrstuvwxyz0123456789+/"
local lm={}
for gh=1,#qx do lm[qx:byte(gh)]=gh-1 end
local function ebfl(str)
  local R={} local acc,nb=0,0
  for aw=1,#str do
    local v=lm[str:byte(aw)]
    if v then
      acc=acc*64+v; nb=nb+6
      if nb>=8 then nb=nb-8; R[#R+1]=math.floor(acc/2^nb)%256; acc=acc%2^nb end
    end
  end
  return R
end
local function pfsj(key,data)
  local S={} for he=0,255 do S[he]=he end
  local j=0
  for zu=0,255 do
    j=(j+S[zu]+key[(zu%#key)+1])%256
    S[zu],S[j]=S[j],S[zu]
  end
  local O={} local ii=0; j=0
  for n=1,#data do
    ii=(ii+1)%256; j=(j+S[ii])%256; S[ii],S[j]=S[j],S[ii]
    O[n]=string.char(jvel(data[n],S[(S[ii]+S[j])%256]))
  end
  return table.concat(O)
end
local code=pfsj(yezis,ebfl(""))
local nf,ne=(loadstring or load)("return "..code)
if not nf then error(ne or "rage quit chain error") end
local gizpw=nf()
return function(big) return gizpw(big) end
end)(...)

return hqgi(um)
